const l = $json;

function ou(v, alt) {
  if (v === null || v === undefined || v === '') return alt;
  return String(v);
}

const hist = Array.isArray(l.historico) ? l.historico : [];
let conversa = '';
for (const m of hist) {
  let quem = 'IA';
  if (m.quem === 'lead') quem = 'LEAD';
  if (m.quem === 'equipe') quem = 'EQUIPE';
  conversa = conversa + '[' + ou(m.em, '?') + '] ' + quem + ': ' +
             ou(m.texto, '(sem texto)') + '\n';
}
if (!conversa) conversa = '(nenhuma mensagem registrada)\n';

const ficha =
  'AGORA: ' + ou(l.agora_local, '?') + ' (America/Sao_Paulo)\n' +
  'Nao agende followup antes de ' + ou(l.minimo_local, '?') +
  ' nem depois de ' + ou(l.limite_local, '?') + '.\n' +
  '\n' +
  'FICHA ATUAL DO LEAD\n' +
  'nome: ' + ou(l.nome, '(desconhecido)') + '\n' +
  'etiqueta: ' + ou(l.etiqueta, 'Novo Lead') + '\n' +
  'origem: ' + ou(l.origem, '(nao sei)') + '\n' +
  'interesse: ' + ou(l.interesse, '(nao sei)') + '\n' +
  'objecao: ' + ou(l.objecao, '(nao sei)') + '\n' +
  'temperatura: ' + ou(l.temperatura, '(nao sei)') + '\n' +
  'data agendada: ' + ou(l.data_agendada_local, '(nenhuma)') + '\n' +
  'resumo anterior: ' + ou(l.resumo, '(nenhum)') + '\n' +
  'followups enviados sem resposta: ' + ou(l.n_toques, '0') + '\n' +
  'minutos desde a ultima mensagem do lead: ' +
  ou(l.min_desde_lead, '(nunca falou)') + '\n' +
  'minutos desde a ultima mensagem da equipe: ' +
  ou(l.min_desde_equipe, '(nunca falou)') + '\n' +
  '\n' +
  'CONVERSA (mais antiga primeiro)\n';

return {
  json: {
    lead_id: l.lead_id,
    etiqueta_atual: ou(l.etiqueta, 'Novo Lead'),
    agora_local: l.agora_local,
    minimo_local: l.minimo_local,
    limite_local: l.limite_local,
    prompt_usuario: ficha + conversa,
  },
};

