const ctx = $('Montar prompt do lead').item.json;
const cru = $json.output === undefined ? $json : $json.output;

const ETIQUETAS = [
  'Novo Lead', 'Atendimento', 'Link enviado', 'Aguardando pagamento',
  'Agendado', 'Aula realizada', 'Follow-up', 'Negociação encerrada'];
const TEMPERATURAS = ['quente', 'morno', 'frio'];
const TIPOS = ['reengajar', 'lembrete_d1', 'lembrete_dia', 'pos_aula'];
const CARIMBO = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/;

function texto(v, max) {
  if (v === null || v === undefined) return '';
  const s = String(v).trim();
  if (!s || s === 'null' || s === 'undefined') return '';
  return s.slice(0, max);
}

function recusar(motivo) {
  return { json: { valido: false, lead_id: ctx.lead_id, erro: motivo } };
}

if (!cru || typeof cru !== 'object') return recusar('a IA nao devolveu objeto');

let etiqueta = texto(cru.etiqueta, 60);
if (etiqueta === 'Negociacao encerrada') etiqueta = 'Negociação encerrada';
if (ETIQUETAS.indexOf(etiqueta) === -1) etiqueta = ctx.etiqueta_atual;

let temperatura = texto(cru.temperatura, 20).toLowerCase();
if (TEMPERATURAS.indexOf(temperatura) === -1) temperatura = '';

const resumo = texto(cru.resumo, 2000);
if (!resumo) return recusar('a IA nao devolveu resumo');

let dataAgendada = texto(cru.data_agendada, 16);
if (dataAgendada && !CARIMBO.test(dataAgendada)) dataAgendada = '';

const f = cru.followup;
let temFollowup = false;
let quando = '';
let tipo = '';
let motivo = '';

if (f && typeof f === 'object') {
  quando = texto(f.quando, 16);
  tipo = texto(f.tipo, 30).toLowerCase();
  motivo = texto(f.motivo, 500);
  if (CARIMBO.test(quando)) {
    if (TIPOS.indexOf(tipo) === -1) tipo = 'reengajar';
    if (quando < ctx.minimo_local) quando = ctx.minimo_local;
    if (quando > ctx.limite_local) quando = ctx.limite_local;
    temFollowup = true;
  }
}

return {
  json: {
    valido: true,
    lead_id: ctx.lead_id,
    etiqueta: etiqueta,
    interesse: texto(cru.interesse, 500),
    objecao: texto(cru.objecao, 500),
    temperatura: temperatura,
    data_agendada: dataAgendada,
    resumo: resumo,
    // Auditoria (§18). Vazio e aceito: campo novo nunca derruba qualificacao.
    justificativa: texto(cru.justificativa_curta, 300),
    tem_followup: temFollowup,
    fup_quando: temFollowup ? quando : '',
    fup_tipo: temFollowup ? tipo : '',
    fup_motivo: temFollowup ? motivo : '',
    erro: '',
  },
};
